#!/bin/sh
# Product verification gate, run before every commit and in CI.
# Generated by fullstack-playbook. Fill the COMMANDS section during onboarding.
set -u
# Run from the product root (two levels above this file), so products in a subfolder work too.
cd "$(dirname "$0")/../.." || exit 1
fail=0

run() {
  echo "-> $*"
  if ! sh -c "$*"; then
    echo "FAILED: $*"
    fail=1
  fi
}

# COMMANDS: one `run` line per check this product has (lint, type check, tests, design tokens,
# secret scan, dependency audit, commit message format). Keep them fast enough for every commit.
# run "<lint command>"
# run "<test command>"

# Notebook check (statuses, blockers, risk answers, locked tests, state). Managed copy kept in
# docs/playbook/tools/ so the gate works even where the skill is not installed.
run "python3 docs/playbook/tools/check_space.py ."

exit $fail
